-- ---- meeting_notes ----
INSERT OR REPLACE INTO meeting_notes (id, project_id, meeting_date, note, created_by, created_at, updated_at) VALUES
  (1, 22, '2026-01-20', '権限を全て繁田さんが持っているため、稟議に時間がかかりそう、且つ別部署でシステムのアップデートを考えているため、その動きを待ってになる', '管理者', '2026-01-20 08:56:12', '2026-01-20 08:56:12'),
  (2, 23, '2026-01-20', '新関さんが提案してくれているため不明', '管理者', '2026-01-20 08:57:09', '2026-01-20 08:57:09'),
  (3, 25, '2026-01-20', '価値は出せているが、マネタイズの方針決定が必要、レベニューシェアなども検討', '管理者', '2026-01-20 08:58:33', '2026-01-20 08:58:33'),
  (4, 26, '2026-01-20', '新規事業担当としてはかなり前向きに新しい提案を欲しがっている。特に地方創生とWeb3などを組み合わせた部分に興味あり。STOと新電力てきな組み合わせで何か考えたい→まずはシンプルに電力事業を自治体と組んで行う→3000世帯くらいをとれると1000万円ほど還元できるので、そのお金を自治体がやりたい事業に投資する形を取りたいとのこと、一旦先方で資料を作成してもらい、天童市、国立市、広島市へアプローチを行う※前には進みそうだが、Web3プロジェクトなどは少し遠そうな予感', '管理者', '2026-01-20 08:59:22', '2026-01-20 08:59:22'),
  (5, 27, '2026-01-20', 'システム刷新のきっかけとなったクライアントとガルディア間で折衝中。案件がまとまり次第本案件を推進したいと考えているが、クライアントをロストした場合、本案件も白紙となる。', '管理者', '2026-01-20 09:00:11', '2026-01-20 09:00:11'),
  (6, 28, '2026-01-20', 'システム刷新に関して検討中。オービックなどのパッケージを利用する方針だが、合わせてスクラッチも検討している。VAとしてAIなどを活用しながら低コストで提案できるのであれば。一旦PMOのニーズを確認中', '管理者', '2026-01-20 09:00:54', '2026-01-20 09:00:54');
